from httpbin.core import app

def test_two_code_comma_list_both_reachable():
    client = app.test_client()
    allowed = {200, 500}
    observed = set()
    for _ in range(80):
        r = client.get('/status/200,500')
        assert r.status_code in allowed, f'Got {r.status_code}, not in {allowed}'
        observed.add(r.status_code)
    assert observed == {200, 500}, f'Expected both codes observed, got {observed}'

from httpbin.core import app

def test_boundary_two_element_list_minimum_comma_case():
    client = app.test_client()
    allowed = {200, 404}
    not_allowed = {201, 403, 500, 301}
    observed = set()
    for _ in range(40):
        r = client.get('/status/200,404')
        assert r.status_code in allowed, f'Got {r.status_code}'
        assert r.status_code not in not_allowed
        observed.add(r.status_code)
    assert len(observed) >= 1
